from lib import *
R=[]
R.append((6466719,{
"es":L("Espárragos con panko y hierbas","Espárragos frescos cubiertos con una salsa cremosa ligera y ácida, y espolvoreados con pan molido crujiente. Esta guarnición rápida y fácil es una deliciosa manera de realzar una cena de cerdo o pollo asado.","4","6 espárragos + 2 cucharadas de salsa + 2 cucharadas de pan molido",
["2 cucharaditas de aceite de oliva extra virgen","1/3 taza de pan molido panko","1 taza de agua","1 libra de espárragos (recortados)","1/4 taza de crema agria (sin grasa)","3 cucharadas de mayonesa light","2 cucharadas de leche (sin grasa)","1 1/2 cucharaditas de mostaza preparada","1/4 cucharadita de estragón seco","1/4 cucharadita de sal"],
["Caliente el aceite en un sartén grande a fuego medio-alto. Agregue el pan molido y cocine de 1 a 2 minutos, o hasta que esté dorado, revolviendo constantemente. Reserve en un plato aparte.","Lleve el agua a hervor en el sartén a fuego medio-alto. Agregue los espárragos, deje que vuelva a hervir, reduzca el fuego, tape y cocine a fuego lento durante 3 minutos o hasta que estén apenas tiernos. Escurra bien y deseche el agua. Coloque los espárragos en un plato para servir.","Mientras tanto, en un tazón pequeño, bata la crema agria, la mayonesa, la leche, la mostaza, el estragón y la sal. Colóquelo en el sartén a fuego medio-bajo y cocine durante 1 minuto o hasta que esté caliente, revolviendo constantemente. Vierta con una cuchara sobre los espárragos y espolvoree con el pan molido."]),
"ar":L("هليون ببقسماط البانكو والأعشاب","هليون طازج مغطى بصلصة كريمية خفيفة وحامضة ومزيّن ببقسماط مقرمش. هذا الطبق الجانبي السريع والسهل طريقة لذيذة لتزيين عشاء من لحم الخنزير أو الدجاج المشوي.","4","6 سيقان هليون + 2 ملعقة كبيرة صلصة + 2 ملعقة كبيرة بقسماط",
["2 ملعقة صغيرة زيت زيتون بكر ممتاز","⅓ كوب بقسماط بانكو","1 كوب ماء","1 رطل هليون (مقصوص)","¼ كوب كريمة حامضة (خالية من الدسم)","3 ملاعق كبيرة مايونيز خفيف","2 ملعقة كبيرة حليب (خالٍ من الدسم)","1½ ملعقة صغيرة خردل جاهز","¼ ملعقة صغيرة طرخون مجفف","¼ ملعقة صغيرة ملح"],
["سخّن الزيت في مقلاة كبيرة على نار متوسطة إلى عالية. أضف البقسماط واطهِه لمدة 1 إلى 2 دقيقة أو حتى يصبح ذهبي اللون مع التحريك المستمر. ضعه جانبًا في طبق منفصل.","اترك الماء يغلي في المقلاة على نار متوسطة إلى عالية. أضف الهليون واتركه يعود إلى الغليان، ثم اخفض النار وغطِّ المقلاة واتركه على نار هادئة لمدة 3 دقائق أو حتى يصبح طريًا فقط. صفِّه جيدًا وتخلص من الماء. ضع الهليون في طبق التقديم.","في الأثناء، في وعاء صغير، اخفق الكريمة الحامضة والمايونيز والحليب والخردل والطرخون والملح. ضعه في المقلاة على نار متوسطة إلى منخفضة واطهِه لمدة دقيقة واحدة أو حتى يسخن مع التحريك المستمر. اسكبه بالملعقة فوق الهليون ورشّ البقسماط."])}))
R.append((6466720,{
"ar":L("مصاصات سموثي التوت الأحمر مناسبة للأطفال","جرّب مصاصات السموثي اللذيذة والسهلة هذه، فهي مثالية في يوم صيفي حار. ولأن محتواها من الكربوهيدرات والسكر أقل من المثلجات الجاهزة، سيحب الأطفال والكبار هذه الحلوى المناسبة لمرضى السكري.","4","1 مصاصة",
["1 حبة موز صغيرة","1 كوب توت أحمر مجمد غير محلى","2 أونصة زبادي يوناني بالتوت (خالٍ من الدسم)","½ كوب حليب خالٍ من الدسم"],
["اخلط جميع المكونات في الخلاط حتى تصبح ناعمة.","اسكب خليط السموثي بالتساوي في 4 قوالب مصاصات مثلجة. أدخل عود المصاصة من الأعلى. ضعها بشكل عمودي وجمّدها حتى تتصلب؛ نحو 3 ساعات."])}))
R.append((6468122,{
"es":L("Orzo con limón, alcachofas y espárragos","Las alcachofas y los espárragos son una combinación perfecta en el mundo culinario y con frecuencia se sirven juntos en los platos típicos italianos. Entre sus muchas similitudes, ambos cultivos son originarios del Mediterráneo y crecen mejor en climas de cálidos a ligeramente frescos. En la cocina, se pueden incorporar a recetas saludables de sopa, pasta, arroz, tortilla y ensalada.","8","1/2 taza",
["1/4 cucharadita de sal","1/2 libra de pasta orzo seca o pasta pequeña sin gluten","1 libra de espárragos frescos o congelados (recortados en trozos de 1 pulgada)","1 paquete (14 onzas) de corazones de alcachofa congelados (descongelados)","1/4 taza de jugo de limón","1 cucharada de ralladura de 1 limón","1/4 cucharadita de pimienta negra","2 cucharadas de aceite de oliva","1/4 taza de queso Pecorino Romano (rallado)"],
["Lleve a hervor una olla grande con agua a fuego alto. Agregue 1/4 cucharadita de sal y reduzca el fuego a medio.","Agregue el orzo y revuelva. Cocine el orzo hasta que esté tierno, pero todavía al dente. Escurra el orzo cuando esté listo y regréselo a la olla.","Mientras tanto, lleve a hervor una olla mediana con agua a fuego alto. Agregue los espárragos y cocine hasta que estén tiernos (unos 5 minutos); luego escúrralos.","Agregue los espárragos, los corazones de alcachofa, el jugo de limón, la ralladura de limón, 1/4 cucharadita más de sal (si lo desea), pimienta recién molida y el aceite de oliva a la olla con el orzo y revuelva.","Pruebe y ajuste la sazón, si es necesario. Decore con el queso y sirva caliente."]),
"ar":L("أورزو بالليمون والخرشوف والهليون","الخرشوف والهليون ثنائي متناغم في عالم الطهي، وكثيرًا ما يُجمع بينهما في الأطباق الإيطالية التقليدية. ومن أوجه التشابه الكثيرة بينهما أن كليهما موطنه الأصلي البحر المتوسط، وينمو أفضل ما يكون في مناخ دافئ إلى معتدل البرودة قليلًا. وفي المطبخ يمكن إدخالهما في وصفات صحية من الشوربة والمعكرونة والأرز والعجة والسلطة.","8","½ كوب",
["¼ ملعقة صغيرة ملح","½ رطل معكرونة أورزو جافة أو معكرونة صغيرة خالية من الغلوتين","1 رطل هليون طازج أو مجمد (مقصوص إلى قطع بطول 1 بوصة)","1 عبوة (14 أونصة) قلوب خرشوف مجمدة (مذابة)","¼ كوب عصير ليمون","1 ملعقة كبيرة قشر ليمونة واحدة مبشور","¼ ملعقة صغيرة فلفل أسود","2 ملعقة كبيرة زيت زيتون","¼ كوب جبن بيكورينو رومانو (مبشور)"],
["اترك قدرًا كبيرًا من الماء يغلي على نار عالية. أضف ¼ ملعقة صغيرة من الملح واخفض النار إلى متوسطة.","أضف الأورزو وقلّب. اطهِ الأورزو حتى ينضج لكن يبقى متماسكًا (آل دنتي). صفِّ الأورزو عندما ينضج وأعده إلى القدر.","في الأثناء، اترك قدرًا متوسط الحجم من الماء يغلي على نار عالية. أضف الهليون واطهِه حتى يصبح طريًا (نحو 5 دقائق)، ثم صفِّه.","أضف الهليون وقلوب الخرشوف وعصير الليمون وقشر الليمون و¼ ملعقة صغيرة إضافية من الملح (إن رغبت) والفلفل المطحون طازجًا وزيت الزيتون إلى القدر الذي فيه الأورزو وقلّب.","تذوّق وعدّل التتبيل إن لزم الأمر. زيّنه بالجبن وقدّمه ساخنًا."])}))
R.append((6468501,{
"ar":L("فطر محشو بالنقانق","الفطر المحشو دائمًا ما يلقى نجاحًا في حفلات الكوكتيل. جرّب هذه الوصفة في لقائك القادم!","6","3 حبات فطر",
["18 حبة فطر كريميني (بيبي بيلا) كبيرة","¾ كوب بقسماط (سادة، مقسم)","2 ملعقة كبيرة جبن بارميزان (مبشور)","2 أونصة نقانق دجاج (مزالة الأغلفة)","1 حبة بصل كبيرة (مفرومة ناعمًا)","1 حبة فلفل رومي أحمر صغيرة (مفرومة ناعمًا)","2 ملعقة كبيرة بقدونس طازج (مفروم ناعمًا)","¼ ملعقة صغيرة فلفل أسود"],
["سخّن الفرن مسبقًا إلى 400° فهرنهايت (200° مئوية). انزع سيقان الفطر واقطعها ناعمًا. اخلط 2 ملعقة كبيرة من البقسماط مع البارميزان في وعاء صغير.","ادهن مقلاة كبيرة غير لاصقة بقليل من بخاخ الطهي وضعها على نار متوسطة. اطهِ النقانق حتى تبدأ بالتحمير، نحو 5 دقائق، مع تفتيتها بجانب الملعقة. أضف البصل والفلفل الأحمر وسيقان الفطر والبقدونس واطهِ حتى تلين الخضار، نحو 5 دقائق. أضف باقي البقسماط والفلفل الأسود. ارفعها عن النار. أضف 1 ملعقة صغيرة من الماء في كل مرة حتى تحصل على حشوة رطبة بما يكفي لتكويمها.","كوّم الحشوة في الفطر ورتّبه، بحيث تكون الحشوة إلى الأعلى، في طبق خبز مقاس 13 × 9 بوصات. رُشّ خليط البارميزان فوقه. اخبزه حتى يسخن جيدًا، نحو 9 دقائق."])}))
R.append((6468907,{
"ar":L("رغيف اللحم بالفطر والجوز","تحافظ هذه الأرغفة على شكلها جيدًا لأنها تُخبز في أطباق رامكن فردية، وهي مثالية للتحكم في حجم الحصة.","4","1 طبق رامكن",
["1 بخّة، 0.25 جم بخاخ طهي غير لاصق","1 ملعقة كبيرة زيت زيتون","½ حبة بصل كبيرة (مفرومة ناعمًا)","12 أونصة فطر مشكل ((أبيض أو كريميني أو بورتوبيلو أو غيره) مزال السيقان ومنظف ومفروم ناعمًا)","⅓ كوب فلفل رومي أحمر (مفروم ناعمًا)","⅓ كوب طماطم مجففة مرطّبة (مفرومة ناعمًا)","1 ملعقة صغيرة توابل إيطالية","½ ملعقة صغيرة ملح كوشر","¼ ملعقة صغيرة فلفل أسود مطحون طازجًا","1 بيضة كبيرة (مخفوقة)","¾ كوب بقسماط بانكو","½ كوب حليب خالٍ من الدسم","½ كوب جوز (مفروم ناعمًا)"],
["سخّن الفرن مسبقًا إلى 350° فهرنهايت (175° مئوية). ادهن 4 أطباق رامكن (سعة 8 أونصات) ببخاخ الطهي. ضعها جانبًا.","سخّن الزيت في مقلاة كبيرة على نار متوسطة. قلّب البصل والفطر لمدة 10 دقائق أو حتى يتحمر جيدًا. أضف الفلفل الأحمر والطماطم المجففة وقلّب نحو 8 دقائق. أضف التوابل الإيطالية والملح والفلفل وقلّب دقيقة واحدة.","ضع خليط الفطر في وعاء كبير واتركه يبرد لمدة دقيقتين. أضف البيض والبقسماط والحليب والجوز. امزج برفق. وزّع الخليط على جميع أطباق الرامكن، مع الضغط عليه ليتسع في جميع الأطباق.","ضع أطباق الرامكن على صينية خبز واخبزها في الفرن لمدة 30 إلى 35 دقيقة حتى يتحمر وجهها. مرّر سكينًا حول كل طبق رامكن لفصل الرغيف"])}))
R.append((6469708,{
"ar":L("سلطة كابريزي الحديقة","يوجد جبن الموزاريلا الطازج في قسم الأطعمة الجاهزة أو مع الأجبان الخاصة. وهو إضافة مثالية غنية بالنكهة لهذه السلطة الصيفية المنعشة!","12","½ كوب",
["8 حبات طماطم برقوقية (روما) (منزوعة البذور ومقطعة إلى قطع بحجم ½ بوصة)","2 حبة خيار متوسطة (منزوعة البذور ومقطعة إلى قطع بحجم ½ بوصة)","½ حبة بصل أحمر صغيرة (مقطعة مكعبات صغيرة)","1 ملعقة كبيرة زيت زيتون","3 ملاعق كبيرة خل بلسمي","1 أونصة ريحان طازج ((نحو 15 ورقة)، مفروم)","¼ ملعقة صغيرة ملح (اختياري)","¼ ملعقة صغيرة فلفل أسود","4 أونصات جبن موزاريلا طازج (مقطع إلى قطع صغيرة)"],
["في وعاء كبير، اخلط جميع المكونات. امزج جيدًا.","اترك السلطة تتتبّل لمدة ساعة في الثلاجة."])}))
R.append((6470032,{
"ar":L("برغر الخضار الاقتصادي مع سلطة الكول سلو بالمانجو","قدّم هذا الطبق النباتي مع شرائح الطماطم وسلطة جبن الموزاريلا الطازج.","6","1 برغر + ¼ كوب كول سلو",
["1 بخّة، 0.25 جم بخاخ طهي غير لاصق","1 علبة (15 أونصة) فاصوليا كانيليني (مشطوفة ومصفاة)","½ كوب بصل (مقطع مكعبات)","1 فص ثوم (مفروم)","1 كوب فطر أبيض (شامبينيون) (مقطع مكعبات)","1 كوب جزر مبشور","1 ملعقة كبيرة صلصة ورسترشير","1 ملعقة كبيرة صلصة صويا أقل صوديومًا","1 كوب شوفان سريع الطهي","2 ملعقة صغيرة توابل الستيك","1 حبة مانجو متوسطة غير ناضجة (مقشرة ومنزوعة النواة ومبشورة)","1 كيس (9 أونصات) خليط كول سلو جاهز","2 ملعقة كبيرة خل النبيذ الأرز","1 ملعقة كبيرة زيت زيتون","6 أوراق خس (كبيرة)"],
["ادهن مقلاة كبيرة غير لاصقة ببخاخ الطهي. ضعها جانبًا.","ضع الفاصوليا الكانيليني والبصل والثوم والفطر والجزر وصلصة ورسترشير وصلصة الصويا والشوفان وتوابل الستيك مونتريال والملح (اختياري) في محضّر الطعام. اخلط على دفعات قصيرة عدة مرات حتى يمتزج الخليط دون أن يتحول إلى عجينة.","قسّم خليط البرغر إلى 6 حصص متساوية وشكّلها أقراصًا.","سخّن المقلاة المجهزة على نار متوسطة إلى عالية. قلّب أقراص البرغر على كل جانب لمدة 6 إلى 8 دقائق. ضعها جانبًا.","في وعاء كبير، اخلط المانجو المبشورة وخليط الكول سلو وخل النبيذ الأرز وزيت الزيتون. قلّب حتى يتغطى الخليط.","ضع قرص برغر على ورقة خس، وضع فوقه ¾ كوب من خليط الكول سلو."])}))
R.append((6470482,{
"ar":L("دجاج مع صلصة الأناناس واليوسفي","تقول مؤلفة كتب الطبخ روبين ويب: \"عندما كنت طفلة، لم أكن في الواقع من محبي الفاكهة الطازجة. لكن اليوسفي المعلب كان يثير حماستي دائمًا، ولدي ذكريات دافئة عن وعاء صغير من الكريستال المنقوش كانت أمي تقدّم فيه فصوص البرتقال الصغيرة. وقد وسّعت بالطبع مجموعة الفاكهة التي أتناولها، لكنني ما زلت أرى أن اليوسفي فاكهة رائعة متعددة الاستعمالات. هنا، تتناغم صلصة بسيطة منكّهة بجوز الهند الاستوائي مع صدور الدجاج المحمّرة المتبّلة بالكمون\".","4","1 صدر + ½ كوب صلصة",
["1 كوب أناناس معلب (بدون سكر مضاف، مصفى جيدًا)","1 كوب يوسفي معلب في الماء أو العصير (مصفى جيدًا، مفروم خشنًا)","2 ساق بصل أخضر (الجزء الأبيض فقط، مفروم ناعمًا)","¼ كوب فلفل رومي أحمر (مفروم ناعمًا)","1½ ملعقة كبيرة رقائق جوز الهند غير المحلاة","¼ ملعقة صغيرة رقائق الفلفل الأحمر المجروشة","1 رطل صدور دجاج بدون عظم وبدون جلد","1 ملعقة صغيرة كمون مطحون","1 ملعقة صغيرة مسحوق الفلفل الحار","¼ ملعقة صغيرة ملح كوشر","⅛ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة زيت نباتي"],
["بطّن صينية خبز بورق الألمنيوم. سخّن الفرن مسبقًا إلى 375 درجة فهرنهايت (190° مئوية). اخلط جميع مكونات الصلصة في وعاء. غطِّه وضعه في الثلاجة لمدة ساعة.","في الأثناء، أزل أي دهون زائدة عن صدور الدجاج. اخلط الكمون ومسحوق الفلفل الحار والملح والفلفل. افرك كل قطعة دجاج بخليط التوابل.","سخّن الزيت في مقلاة كبيرة على نار متوسطة إلى عالية. أضف الدجاج وحمّره من الجانبين لمدة 10 دقائق إجمالًا. ضع الدجاج على صينية الخبز المجهزة. غطِّه بشكل فضفاض بورق الألمنيوم أو ورق الزبدة. تابع طهي صدور الدجاج حتى تنضج تمامًا، نحو 6 إلى 7 دقائق.","اترك الصلصة حتى تصل إلى درجة حرارة الغرفة. قدّم الدجاج المطهو مع الصلصة."])}))
R.append((6471870,{
"es":L("Ramen de tofu, hongos y bok choy","¿Le encanta el ramen? ¡Pruebe esta alternativa más ligera y vegetariana! Agregue un chorrito de sriracha si prefiere su ramen picante.","4","2 tazas",
["4 onzas de fideos ramen secos","1 cucharada de aceite de sésamo","1 cebolla amarilla mediana (en rodajas finas)","2 dientes de ajo (picados)","1 cucharada de jengibre fresco (rallado)","3 tazas de caldo de verduras bajo en sodio","2 tazas de agua","1 taza de hongos shiitake (en rodajas)","1 taza de brócoli (en floretes)","4 tallos de bok choy baby (picados)","5 onzas de zanahorias (ralladas)","14 onzas de tofu extrafirme (escurrido, prensado y cortado en cubos)","1 1/2 cucharadas de aminos de coco","1 cucharada de vinagre de arroz","2 tallos de cebollín (picados)"],
["Cocine los fideos ramen según las instrucciones del paquete. Escurra y reserve.","En una olla grande, caliente el aceite de sésamo a fuego medio. Agregue la cebolla en rodajas, el ajo picado y el jengibre rallado. Saltee hasta que la cebolla esté translúcida.","Vierta el caldo de verduras y el agua y lleve a fuego lento.","Agregue a la olla los hongos en rodajas, los floretes de brócoli, el bok choy picado, las zanahorias ralladas y el tofu en cubos. Cocine a fuego lento de 5 a 7 minutos, hasta que las verduras estén tiernas.","Incorpore los aminos de coco y el vinagre de arroz.","Divida los fideos ramen cocidos entre los tazones para servir. Sirva con un cucharón el caldo con abundantes verduras sobre los fideos y decore con el cebollín."]),
"ar":L("رامن بالتوفو والفطر وبوك تشوي","هل تحب الرامن؟ جرّب هذا البديل النباتي الأخف! أضف رشة من صلصة سريراتشا إن كنت تفضل الرامن حارًا.","4","2 كوب",
["4 أونصات نودلز رامن جافة","1 ملعقة كبيرة زيت سمسم","1 حبة بصل أصفر متوسطة (مقطعة شرائح رفيعة)","2 فص ثوم (مفروم)","1 ملعقة كبيرة زنجبيل طازج (مبشور)","3 أكواب مرق خضار قليل الصوديوم","2 كوب ماء","1 كوب فطر شيتاكي (مقطع شرائح)","1 كوب بروكلي (زهيرات)","4 سيقان بوك تشوي صغير (مفرومة)","5 أونصات جزر (مبشور)","14 أونصة توفو شديد الصلابة (مصفى ومضغوط ومقطع مكعبات)","1½ ملعقة كبيرة أمينو جوز الهند","1 ملعقة كبيرة خل الأرز","2 ساق بصل أخضر (مفروم)"],
["اسلق نودلز الرامن وفق تعليمات العبوة. صفِّها وضعها جانبًا.","في قدر كبير، سخّن زيت السمسم على نار متوسطة. أضف شرائح البصل والثوم المفروم والزنجبيل المبشور. قلّب حتى يصبح البصل شفافًا.","اسكب مرق الخضار والماء واتركه حتى يغلي غليانًا هادئًا.","أضف شرائح الفطر وزهيرات البروكلي والبوك تشوي المفروم والجزر المبشور والتوفو المقطع مكعبات إلى القدر. اتركها على نار هادئة لمدة 5 إلى 7 دقائق تقريبًا حتى تصبح الخضار طرية.","أضف أمينو جوز الهند وخل الأرز وقلّب.","وزّع نودلز الرامن المطهوة على أوعية التقديم. اسكب المرق الغني بالخضار فوق النودلز بالمغرفة وزيّنه بالبصل الأخضر."])}))
R.append((6472756,{
"ar":L("سمك جامايكي محشو ببسكويت ريتز","هذه الوصفة من وصفات العائلة المفضلة. السمكة كاملة، وعادة ما تكون من سمك السنابر ذي الذيل الأصفر أو سمك الببغاء، وتُحشى كاملة وتُربط بخيوط من ورق الموز وتوضع على عصي كبيرة، حيث تُطهى على نار مكشوفة.","4","½ سمكة سلمون مرقط (نحو 5 أونصات)",
["2 سمكة سلمون مرقط كاملة صغيرة أو 4 شرائح (بالجلد) (أو استخدم سمك السنابر، منظفة ومزالة الحراشف ومخدشة بنمط متقاطع)","2 بخّة، 0.5 جم بخاخ زيت زيتون بكر ممتاز غير لاصق","1 عصير ليمونة خضراء واحدة","1 رشة ملح كوشر (حسب الرغبة)","½ كوب بسكويت قمح كامل (مجروش)","½ كوب بسكويت ريتز من القمح الكامل (مجروش)","1 ملعقة صغيرة زعتر طازج (مفروم ناعمًا)","1 حبة فلفل حار كاملة (منزوعة البذور ومفرومة ناعمًا، مثل سكوتش بونيت أو سيرانو أو هالبينو)","1 حزمة (نحو 5 سيقان) بصل أخضر (مفروم)","1 ملعقة كبيرة سمن نباتي (مارجرين) (دهن بنكهة الزبدة، مذاب)"],
["اخدش جلد السمكة بسكين حادة. رُشّ السطح المخدوش من السمكة ببخاخ الطهي. اعصر الليمون الأخضر فوق الجلد ورشّ الملح. افرك السطح بالخليط.","حضّر الحشوة بخلط البسكويت المجروش والزعتر والفلفل الحار والبصل الأخضر والزبدة المذابة في وعاء متوسط. املأ تجويف السمكة بالحشوة، وباستخدام عود أسنان أو سيخ معدني ثبّت الفتحة بنسج السيخ لإغلاق السمكة. يمكنك أيضًا غرس أعواد الأسنان في أسفل السمكة على مسافات 2 بوصة للتثبيت.","سخّن الشواية مسبقًا على حرارة متوسطة إلى عالية وضع السمكة على شبكة الشواء. اطهِها لمدة 15 إلى 18 دقيقة مع قلبها من حين لآخر، حتى تنضج وتتكون قشرة مقرمشة على الخارج."])}))
R.append((6473360,{
"ar":L("لازانيا السبانخ الخالية من الغلوتين في الطنجرة البطيئة","هذه الوصفة سريعة ولذيذة وتقدم وجبة مريحة ستستمتع بها العائلة كلها. يجب تجربتها!","12","1 قطعة (1/12 من الوصفة)",
["9 صفائح لازانيا (خالية من الغلوتين)","24½ أونصة صلصة طماطم للمعكرونة معبأة في برطمان (أقل صوديومًا)","1 عبوة سبانخ مجمدة (10 أونصات، مفرومة، مذابة ومصفاة)","1 كوب جبن موزاريلا نصف منزوع الدسم (مبشور، مقسم)","1 كوب جبن ريكوتا قليل الدسم","1 بخّة بخاخ طهي غير لاصق","¼ كوب جبن بارميزان (مبشور طازجًا)","8 أونصات صلصة طماطم (1 علبة 8 أونصات، بدون ملح مضاف)"],
["رُشّ الطنجرة البطيئة ببخاخ الطهي.","في وعاء متوسط، اخلط جبن الريكوتا وجبن البارميزان و¼ كوب من جبن الموزاريلا والسبانخ.","افرد 1 كوب من صلصة المعكرونة في قاع الطنجرة البطيئة. رتّب 3 صفائح لازانيا جنبًا إلى جنب فوق الصلصة، واكسر الصفائح لتناسب الحجم إن لزم الأمر.","افرد نحو ⅓ كوب من خليط الريكوتا والسبانخ فوق الصفائح. كرر الطبقات من صلصة المعكرونة والصفائح وخليط الريكوتا والسبانخ مرتين أخريين. غطِّ الوجه بما تبقى من صلصة المعكرونة وصلصة الطماطم المعلبة. رُشّ 1 كوب من جبن الموزاريلا على الوجه.","ضع الغطاء على الطنجرة البطيئة. اطهِ على الإعداد المنخفض لمدة 2 إلى 3 ساعات أو حتى تنضج (تختلف مدة الطهي بحسب الطنجرة البطيئة).","* جُرّبت هذه الوصفة بصفائح لازانيا خالية من الغلوتين، ولكن يمكن استخدام صفائح لازانيا من القمح الكامل."])}))
